<!doctype html><html lang="vi"><head><meta charset="utf-8"><title>Hóa đơn {{ $invoice->MAHD }}</title><style>body{font-family:Arial,sans-serif;max-width:850px;margin:40px auto;padding:20px;color:#172435}h1{color:#086493}table{width:100%;border-collapse:collapse;margin-top:25px}th,td{padding:12px;border-bottom:1px solid #ddd;text-align:left}.total{text-align:right;margin-top:25px}@media print{body{margin:0}}</style></head><body><h1>THE GYM · HÓA ĐƠN #{{ $invoice->MAHD }}</h1><p>Khách hàng: {{ $invoice->TENKH }} · {{ $invoice->SDT }}</p><p>Ngày lập: {{ $invoice->NGAYLAP }} · {{ $invoice->TRANGTHAI }}</p><table><thead><tr><th>Hàng hóa/dịch vụ</th><th>Số lượng/buổi</th><th>Đơn giá</th><th>Thành tiền</th></tr></thead><tbody>@foreach ($lines as $line)<tr><td>{{ $line->TENHANG }}</td><td>{{ $line->SOLUONG }}</td><td>@if (isset($line->ORIGINAL_DONGIA) && $line->ORIGINAL_DONGIA !== null && (int) $line->ORIGINAL_DONGIA > (int) $line->DONGIA)<span style="color:#64748b;text-decoration:line-through">{{ number_format($line->ORIGINAL_DONGIA, 0, ',', '.') }}đ</span><br>Giá khuyến mãi: {{ number_format($line->DONGIA, 0, ',', '.') }}đ @else{{ number_format($line->DONGIA, 0, ',', '.') }}đ@endif</td><td>{{ number_format($line->THANHTIEN_SP, 0, ',', '.') }}đ</td></tr>@endforeach</tbody></table><div class="total"><p>Tiền hàng/dịch vụ: {{ number_format($invoice->TONGTIEN, 0, ',', '.') }}đ</p>@if ((int) $invoice->GIAMGIA > 0 && $discountSnapshot)<p>Ưu đãi hạng {{ $discountSnapshot->tier_name }} ({{ $discountSnapshot->rate_percent }}%) trên {{ number_format($discountSnapshot->base_amount, 0, ',', '.') }}đ: −{{ number_format($discountSnapshot->discount_amount, 0, ',', '.') }}đ</p>@elseif ((int) $invoice->GIAMGIA > 0)<p>Giảm giá theo dữ liệu hóa đơn cũ — chưa xác định nguồn: −{{ number_format((int) $invoice->GIAMGIA, 0, ',', '.') }}đ</p>@else<p>Giảm giá: 0đ</p>@endif<p>Phí giao hàng: {{ number_format($invoice->shipping_fee ?? 0, 0, ',', '.') }}đ</p><h2>Thành tiền: {{ number_format($invoice->THANHTIEN, 0, ',', '.') }} VNĐ</h2></div><p>Cảm ơn bạn đã lựa chọn The Gym.</p></body></html>
